// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;

    function setUp() public { c = new EBU(); }

    // We fuzz the caller `from`, one recipient `to`, and an amount `amt`.
    // We keep the scenario minimal by making _tos length == 1 so that C will make exactly one external call,
    // and we deploy a RecordingCounterparty that implements transferFrom(address,address,uint256) and returns true.
    // The general rule: if c.transfer(...) does not revert then it must return true. The mutant that returns false
    // on success will violate this for some inputs; the fuzzer can discover those inputs.
    function testFuzz_property(address from, address to, uint256 amt) public {
        // keep addresses non-zero to be in a wide admissible domain
        vm.assume(from != address(0));
        vm.assume(to != address(0));
        // Bound amt to a reasonable range but keep wide
        amt = bound(amt, 0, type(uint256).max);

        // Deploy a recorder that will accept the call and return true
        Recorder rec = new Recorder();

        // Prepare single-element arrays
        address[] memory tos = new address[](1);
        tos[0] = to;
        uint256[] memory vals = new uint256[](1);
        vals[0] = amt;

        // The C contract will low-level call the provided caddress with selector transferFrom(address,address,uint256)
        // Our Recorder implements that function and returns true. Make the call and capture whether it reverted and the return value.
        bool completed;
        bool ret;
        try c.transfer(from, address(rec), tos, vals) returns (bool r) {
            completed = true;
            ret = r;
        } catch {
            completed = false;
            ret = false;
        }

        // General rule: whenever the call completes (does not revert), it must return true.
        // The reference C satisfies: completed ==> ret == true. The mutant (that returns false) violates this for some inputs.
        assertTrue(!completed || ret);
    }
}

// Recorder that matches the selector C uses: transferFrom(address,address,uint256)
// It records calls (count) and returns true to indicate success.
contract Recorder {
    uint256 public calls;
    address public last_from;
    address public last_to;
    uint256 public last_value;

    // Match the selector and signature used by C
    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        calls += 1;
        last_from = from;
        last_to = to;
        last_value = value;
        return true;
    }
}
